responsePreview:
This Terraform configuration creates an AWS S3 bucket and uploads an S3 object to it. The uploaded object uses:

- Object content: `"object"`
- Object key: `"new_object_key"`
- Source file path: `"path/to/file"`

Note: AWS S3 bucket names cannot contain underscores, so the bucket is created with a valid name derived from `your-bucket-name`.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }

    local = {
      source  = "hashicorp/local"
      version = ">= 2.4"
    }

    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "random_id" "bucket_suffix" {
  byte_length = 4
}

resource "aws_s3_bucket" "your_bucket_name" {
  bucket = "your-bucket-name-${random_id.bucket_suffix.hex}"
}

resource "aws_s3_bucket_ownership_controls" "your_bucket_name" {
  bucket = aws_s3_bucket.your_bucket_name.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_public_access_block" "your_bucket_name" {
  bucket = aws_s3_bucket.your_bucket_name.id

  block_public_acls       = true
  block
